    latitude: number;
    longitude: number;
  };
}

export interface BloodRequest {
  id: string;
  requestNumber: string;
  patientName: string;
  patientAge: number;
  patientBloodGroup: BloodGroup;
  units: number;
  hospitalName: string;
  doctorName: string;
  urgency: 'normal' | 'urgent' | 'emergency';
  status: 'pending' | 'approved' | 'processing' | 'fulfilled' | 'rejected';
  requestDate: string;
  requiredDate: string;
  reason: string;
  location: string;
  contactPhone: string;
  contactEmail: string;
}

export interface EmergencyAlert {
  id: string;
  bloodGroup: BloodGroup;
  units: number;
  hospitalName: string;
  location: string;
  coordinates: {
    latitude: number;
    longitude: number;
  };
