    labels: string[];
    values: number[];
  };
}

export interface DonationCertificate {
  id: string;
  donorName: string;
  bloodGroup: BloodGroup;
  donationDate: string;
  units: number;
  hospitalName: string;
  certificateNumber: string;
  issuedBy: string;
