  sortBy: 'distance' | 'rating' | 'donations';
}

export interface DonationReminder {
  id: string;
  donorId: string;
  nextEligibleDate: string;
  reminderDate: string;
  status: 'pending' | 'sent' | 'cancelled';
  type: 'email' | 'sms' | 'push';
  message: string;
  createdAt: string;
}

// src/types/womenCare.ts

export interface PregnancyRecord {
  id: string;
  userId: string;
  
  // Basic Info
